actions.diff:
--- a/secp256r1/src/field.rs
+++ b/secp256r1/src/field.rs
@@ -165,6 +165,12 @@
-        let (difference, borrow) = sub_limbs(self.limbs, rhs.limbs);
-        let (corrected, _) = add_limbs(difference, MODULUS);
-
-        Self {
-            limbs: if borrow == 0 { difference } else { corrected },
-        }
+        let (d, borrow) = sub_limbs(self.limbs, rhs.limbs);
+
+        // Add p back only when the subtraction borrowed.
+        let mask = 0u64.wrapping_sub(borrow);
+        let (w0, carry) = adc(d[0], MODULUS[0] & mask, 0);
+        let (w1, carry) = adc(d[1], MODULUS[1] & mask, carry);
+        let (w2, carry) = adc(d[2], MODULUS[2] & mask, carry);
+        let (w3, _) = adc(d[3], MODULUS[3] & mask, carry);
+
+        Self {
+            limbs: [w0, w1, w2, w3],
+        }

--- a/secp256r1/src/field.rs
+++ b/secp256r1/src/field.rs
@@ -199,2 +199,5 @@
-            Self::ZERO - self
-        }
+            // self is canonical and nonzero, so p - self needs no reduction.
+            Self {
+                limbs: sub_limbs(MODULUS, self.limbs).0,
+            }
+        }

